"""Generate supabase/migrations/0001_init.sql from the SQLAlchemy models (single source of truth) + RLS policies.

Run from backend/:  python -m scripts.gen_migration
"""
from pathlib import Path

from sqlalchemy.dialects import postgresql
from sqlalchemy.schema import CreateIndex, CreateTable

from app import models  # noqa: F401  (registers tables)
from app.db import Base

TENANT_TABLES = [t.name for t in Base.metadata.sorted_tables if "merchant_id" in t.c or t.name == "merchants"]

HEADER = """-- RecoverAI schema for Supabase PostgreSQL.
-- GENERATED by backend/scripts/gen_migration.py from app/models.py — do not edit by hand.
--
-- Security model
--   * The browser never talks to these tables. All access goes through the RecoverAI API, which connects with the
--     database owner role and scopes every query to the authenticated merchant (tenant isolation tested in
--     tests/test_platform.py::test_merchant_cannot_see_other_merchants_data).
--   * Row Level Security is ENABLED on every table with NO policies for the `anon` and `authenticated` roles, so the
--     Supabase public/anon key cannot read or write any financial data even if it leaks.
--   * If you later expose tables to Supabase Auth users directly, add per-tenant policies like the commented example.
--   * Money is integer minor units (cents). No raw card data is ever stored.

BEGIN;
"""

FOOTER = """
-- Example tenant policy (disabled; only needed if browsers query Supabase directly with Supabase Auth):
-- create policy tenant_read on payments for select to authenticated
--   using (merchant_id = (select merchant_id from users where users.id = auth.uid()::text));

COMMIT;
"""


def main():
    dialect = postgresql.dialect()
    out = [HEADER]
    for table in Base.metadata.sorted_tables:
        out.append(str(CreateTable(table).compile(dialect=dialect)).strip() + ";\n")
        for idx in table.indexes:
            out.append(str(CreateIndex(idx).compile(dialect=dialect)).strip() + ";\n")
    out.append("\n-- Row Level Security: deny-by-default for Supabase client roles\n")
    for t in Base.metadata.sorted_tables:
        out.append(f"ALTER TABLE {t.name} ENABLE ROW LEVEL SECURITY;\n")
        out.append(f"REVOKE ALL ON {t.name} FROM anon, authenticated;\n")
    out.append(FOOTER)
    path = Path(__file__).resolve().parents[2] / "supabase" / "migrations" / "0001_init.sql"
    path.write_text("".join(out).replace("DATETIME", "TIMESTAMP WITH TIME ZONE"))
    print(f"wrote {path} ({len(Base.metadata.sorted_tables)} tables)")


if __name__ == "__main__":
    main()
